#!/usr/bin/env bash
# ============================================================
#  AZ L2TP VPN — نصب‌کننده‌ی خودکار (پنل + IPsec + xl2tpd)
#
#  مصرف:
#    bash install.sh                          # رمزها رندوم ساخته میشه
#    bash install.sh --psk MYPSK             # PSK دلخواه
#    bash install.sh --password MYPASS       # رمز ورود پنل دلخواه
#    bash install.sh --server 1.2.3.4        # آدرس سرور (پیش‌فرض: تشخیص خودکار)
#    bash install.sh --psk A --password B --server vpn.example.com
#
#  در پایان، رمز ورود و PSK چاپ میشه.
# ============================================================
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" 2>/dev/null && pwd)" || SCRIPT_DIR="/tmp"
FILES="$SCRIPT_DIR/files"

# حالت «یه خطی»: اگه اسکریپت از اینترنت pipe بشه (curl | bash)، فایل‌های کنارش نیستن
# → از بسته‌ی جاسازی‌شده داخل خود اسکریپت استخراج میشه
FILES_B64=''
if [ ! -d "$FILES" ] || [ ! -f "$FILES/ipsec.conf" ]; then
  TMPD="$(mktemp -d /tmp/l2tp-installer.XXXXXX)"
  trap 'rm -rf "$TMPD"' EXIT
  mkdir -p "$TMPD"
  printf '%s' "$FILES_B64" | base64 -d | tar -xz -C "$TMPD" 2>/dev/null \
    || { echo "✗ استخراج فایل‌های نصب ناموفق بود"; exit 1; }
  FILES="$TMPD/files"
  [ -f "$FILES/ipsec.conf" ] || { echo "✗ بسته‌ی نصب خرابه"; exit 1; }
fi
PANEL_DIR="/root/l2tp-panel"
CHAIN="L2TP_QUOTA"
POOL_NET="192.168.42.0/24"
XAUTH_NET="192.168.43.0/24"

SERVER_IP="" PSK="" ADMIN_PASS=""

RED()  { printf '\033[1;31m%s\033[0m\n' "$*"; }
GRN()  { printf '\033[1;32m%s\033[0m\n' "$*"; }
BLU()  { printf '\033[1;34m%s\033[0m\n' "$*"; }
STEP() { echo; BLU "──── [$1] $2 ────"; }
die()  { RED "✗ $*"; exit 1; }

while [ $# -gt 0 ]; do
  case "$1" in
    --server)   SERVER_IP="$2"; shift 2 ;;
    --psk)      PSK="$2";       shift 2 ;;
    --password) ADMIN_PASS="$2"; shift 2 ;;
    -h|--help)  grep '^#' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) die "آرگومان ناشناخته: $1  (برای راهنما: bash install.sh --help)" ;;
  esac
done

[ "$(id -u)" = "0" ] || die "با root اجرا کن"
[ -d "$FILES" ] || die "پوشه files/ کنار اسکریپت پیدا نشد: $FILES"

# ---------- تشخیص آدرس سرور ----------
STEP "1" "تشخیص آدرس سرور"
if [ -z "$SERVER_IP" ]; then
  SERVER_IP="$(curl -4 -s --max-time 8 https://api.ipify.org || true)"
  [ -n "$SERVER_IP" ] || SERVER_IP="$(curl -4 -s --max-time 8 https://ifconfig.me || true)"
  [ -n "$SERVER_IP" ] || die "تشخیص IP ممکن نشد — با --server <آدرس> اجرا کن"
fi
GRN "  آدرس سرور: $SERVER_IP"

# ---------- PSK ----------
STEP "2" "کلید اشتراکی (PSK)"
if [ -z "$PSK" ]; then
  PSK="$(head -c 24 /dev/urandom | base64 | tr -d '/+=' | cut -c1-24)"
  GRN "  رندوم ساخته شد"
else
  GRN "  از ورودی گرفته شد"
fi

# ---------- پکیج‌ها ----------
STEP "3" "نصب پکیج‌ها"
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq >/dev/null 2>&1 || true
apt-get install -y -qq libreswan xl2tpd ppp python3-flask iptables-persistent curl >/dev/null 2>&1 \
  || die "خطا در نصب پکیج‌ها"
GRN "  libreswan + xl2tpd + ppp + flask + iptables-persistent ✓"

# ---------- توقف سرویس‌های قبلی (برای نصب مجدد امن) ----------
STEP "4" "توقف سرویس‌های قبلی"
for s in ipsec xl2tpd l2tp-panel; do systemctl stop "$s" 2>/dev/null || true; done
GRN "  انجام شد"

# ---------- بکاپ قبلی ----------
STEP "5" "بکاپ نسخه قبلی"
BK="/root/l2tp-backup-$(date +%Y%m%d_%H%M%S)"
mkdir -p "$BK"
for p in /etc/ipsec.conf /etc/ipsec.secrets /etc/ipsec.d /etc/xl2tpd /etc/ppp/chap-secrets "$PANEL_DIR"; do
  [ -e "$p" ] && cp -a "$p" "$BK/" 2>/dev/null || true
done
GRN "  بکاپ: $BK"

# ---------- کپی فایل‌ها ----------
STEP "6" "کپی کانفیگ‌ها و پنل"
# گواهی‌های NSS پنل IPsec (برای ikev2)
mkdir -p /etc/ipsec.d
cp -a "$FILES/ipsec.d/." /etc/ipsec.d/
# کانفیگ IPsec
cp -a "$FILES/ipsec.conf" /etc/ipsec.conf
sed -i "s/__SERVER_IP__/$SERVER_IP/g" /etc/ipsec.conf
# PSK
umask 077
printf '%%any  %%any  : PSK "%s"\n' "$PSK" > /etc/ipsec.secrets
chmod 600 /etc/ipsec.secrets
# xl2tpd + ppp
cp -a "$FILES/xl2tpd.conf"   /etc/xl2tpd/xl2tpd.conf
cp -a "$FILES/l2tp-secrets"  /etc/xl2tpd/l2tp-secrets
chmod 600 /etc/xl2tpd/l2tp-secrets
cp -a "$FILES/ppp-options.xl2tpd" /etc/ppp/options.xl2tpd
cp -a "$FILES/ppp-chap-secrets"   /etc/ppp/chap-secrets
chmod 600 /etc/ppp/chap-secrets
# پنل
mkdir -p "$PANEL_DIR"
cp -a "$FILES/panel/app.py" "$PANEL_DIR/app.py"
if [ -n "$ADMIN_PASS" ]; then
  printf '%s' "$ADMIN_PASS" > "$PANEL_DIR/.admin_pass"
  chmod 600 "$PANEL_DIR/.admin_pass"
  GRN "  رمز پنل: از ورودی گرفته شد"
else
  rm -f "$PANEL_DIR/.admin_pass"     # پنل خودش رندوم میسازه
  GRN "  رمز پنل: رندوم (توسط پنل ساخته میشه)"
fi
rm -f "$PANEL_DIR/.secret_key"       # پنل خودش میسازه
cp -a "$FILES/l2tp-panel.service" /etc/systemd/system/
GRN "  فایل‌ها کپی شد ✓"

# ---------- شبکه ----------
STEP "7" "شبکه و فایروال"
NIC="$(ip route get 1.1.1.1 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev") print $(i+1)}' | head -1)"
[ -n "$NIC" ] || NIC="eth0"
GRN "  کارت شبکه: $NIC"

cat > /etc/sysctl.d/99-l2tp.conf <<EOF
net.ipv4.ip_forward = 1
EOF
sysctl --system >/dev/null 2>&1 || sysctl -w net.ipv4.ip_forward=1 >/dev/null
GRN "  ip_forward=1 ✓"

# زنجیره کووتای حجم (پنل مدیریتش میکنه)
iptables -N "$CHAIN" 2>/dev/null || iptables -F "$CHAIN"
add() { # add <table-flag> <chain> <rule...>
  local tbl="$1"; shift
  local chain="$1"; shift
  if [ "$tbl" = "nat" ]; then
    iptables -t nat -C "$chain" "$@" 2>/dev/null || iptables -t nat -A "$chain" "$@"
  else
    iptables -C "$chain" "$@" 2>/dev/null || iptables -A "$chain" "$@"
  fi
}
# FORWARD
add "" FORWARD -d "$POOL_NET" -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
add "" FORWARD -s "$POOL_NET" -j ACCEPT
add "" FORWARD -d "$POOL_NET" -i "$NIC" -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
add "" FORWARD -s "$POOL_NET" -o "$NIC" -j ACCEPT
add "" FORWARD -j "$CHAIN"
add "" FORWARD -d "$XAUTH_NET" -i "$NIC" -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
add "" FORWARD -s "$XAUTH_NET" -o "$NIC" -j ACCEPT
add "" FORWARD -s "$XAUTH_NET" -o ppp+ -j ACCEPT
# NAT
add nat POSTROUTING -s "$POOL_NET" -j MASQUERADE
add nat POSTROUTING -s "$POOL_NET" -o "$NIC" -j MASQUERADE
add nat POSTROUTING -s "$XAUTH_NET" -o "$NIC" -m policy --dir out --pol none -j MASQUERADE
iptables-save > /etc/iptables/rules.v4 2>/dev/null || true
systemctl enable netfilter-persistent >/dev/null 2>&1 || true
GRN "  قوانین فایروال اعمال و ذخیره شد ✓"

# ---------- سرویس‌ها ----------
STEP "8" "فعال‌سازی سرویس‌ها"
systemctl daemon-reload
for s in ipsec xl2tpd l2tp-panel; do
  systemctl enable "$s" >/dev/null 2>&1 || true
  systemctl restart "$s" 2>/dev/null || systemctl start "$s" 2>/dev/null || true
done
sleep 6
for s in ipsec xl2tpd l2tp-panel; do
  st="$(systemctl is-active "$s" 2>&1)"
  if [ "$st" = "active" ]; then GRN "  $s: active ✓"; else RED "  $s: $st"; fi
done

# ---------- خلاصه ----------
ACTUAL_PASS="$(cat "$PANEL_DIR/.admin_pass" 2>/dev/null || echo '?')"
echo
BLU "══════════════ نصب کامل شد ══════════════"
cat <<SUMMARY

  🌐 پنل مدیریت :  http://$SERVER_IP:8085/
  🔑 رمز ورود    :  $ACTUAL_PASS
  🔏 PSK (L2TP)  :  $PSK
  📦 آدرس سرور   :  $SERVER_IP
  🧩 استخر IP    :  192.168.42.20 - 192.168.42.99  (پنل: .100 - .199)

  ➕ افزودن کاربر: از داخل پنل → «افزودن کاربر»
  📋 اتصال گوشی : L2TP/IPsec با آدرس $SERVER_IP + PSK بالا

  ⚠️  فایروال سرور باید پورت‌های UDP 500، 4500 و 1701 رو باز کنه
SUMMARY
BLU "════════════════════════════════════════"
